import re,glob
for f in sorted(glob.glob("S0*/*.md")):
    t=open(f).read()
    entries=re.findall(r"^\*\*(\S+)\*\* \(\S+\)\n\nSource: \S+ @ [0-9a-f]+\n\n((?:.|\n)*?)(?=\n\n\*\*|\n\n<!--|\Z)",t,re.M)
    for e in entries:
        if e[1].count("\n\n")>0 and "<!--" not in e[1]:
            print(f, e[0]); print(e[1][:500]); print("-----"); break
    else:
        continue
    break
EOF

